"""
Seating Planner module.
"""

__all__ = ["Seat", "Passenger"]
__version__ = "0.1.0"

class Seat:
    def __init__(self, seat_number: int):
        self.seat_number = seat_number

class Passenger:
    def __init__(self, name: str):
        self.name = name

class SeatingPlanner:
    def __init__(self):
        self.seats = {}
        self.passengers = {}

    def add_seat(self, seat: Seat):
        self.seats[seat.seat_number] = seat

    def add_passenger(self, passenger: Passenger, seat_number: int):
        if seat_number in self.seats:
            self.seats[seat_number].assign_passenger(passenger)

    def get_seat(self, seat_number: int) -> Seat:
        return self.seats.get(seat_number)

    def get_passenger(self, name: str):
        for passenger in self.passengers:
            if passenger.name == name:
                return passenger
        return None
